document.addEventListener("DOMContentLoaded",()=>{const e="http://192.168.3.85:9090/report/pdf",t=document.getElementById("all-time-select"),n=document.getElementById("part-time-select"),d=document.getElementById("btn-download-all"),o=document.getElementById("btn-download-part"),a=document.getElementById("start-time"),l=document.getElementById("end-time");function r(e){const t=document.createElement("a");t.href=e,document.body.appendChild(t),t.click(),t.remove()}d.addEventListener("click",()=>{const n=t.value;if(!n)return void alert("Please select a report type for all time ranges to download!");r(`${e}/${n}`)}),o.addEventListener("click",()=>{const t=n.value,d=a.value,o=l.value;if(!t)return void alert("Please select a report type for the specific time range to download!");if(!d||!o)return void alert("Please select both the start time and end time!");const i=Math.floor(new Date(d).getTime()/1e3),m=Math.floor(new Date(o).getTime()/1e3);if(i>=m)return void alert("Start time must be earlier than end time!");r(`${e}/${t}/betweenTimes?start=${i}&end=${m}`)})});